var ITEMS=[["What accountants do","Accountants record, analyze, and report financial activity: bookkeeping, tax preparation, audits, and advisory. Public accountants serve clients; private accountants work inside companies. The CPA license is the gold cre"], ["Key skills","Double-entry bookkeeping fluency, financial statement analysis, tax code navigation, Excel mastery (pivot tables, lookups), attention to detail that borders on superpower, and explaining numbers to non-accountants. Ethic"], ["Tools of the trade","Excel, QuickBooks or Xero, tax software (ProSeries, Lacerte), audit workpaper systems, PDF tools, a 10-key touch skill, and a good calculator. Cloud accounting runs the modern practice."], ["A day in the life","Tax season: returns, extensions, and deadlines. Off-season: bookkeeping cleanups, payroll, advisory, audits, and planning. Month-end closes are the recurring heartbeat."], ["Getting started","Accounting degree, then 150 credit hours for CPA eligibility in most states. Pass the four-part CPA exam while working. Start in public accounting for the fastest learning; industry for work-life balance."], ["Pro tips","Reconcile everything \u2014 unreconciled accounts hide fraud and errors. Document your workpapers like a stranger will review them. Never sign what you do not understand. Specialize: tax, audit, or advisory."], ["GAAP","Profession term \u2014 GAAP: Generally Accepted Accounting Principles."], ["Double-entry","Profession term \u2014 Double-entry: Every transaction hits two accounts: debit and credit."], ["Trial balance","Profession term \u2014 Trial balance: The debit-credit equality check."], ["Balance sheet","Profession term \u2014 Balance sheet: Assets = liabilities + equity at a point in time."], ["Income statement","Profession term \u2014 Income statement: Revenues minus expenses over a period."], ["Cash flow statement","Profession term \u2014 Cash flow statement: Where cash actually went."], ["Accrual","Profession term \u2014 Accrual: Recording when earned/incurred, not when cash moves."], ["Depreciation","Profession term \u2014 Depreciation: Spreading asset cost over its life."], ["Amortization","Profession term \u2014 Amortization: The intangible-asset version of depreciation."], ["Ledger","Profession term \u2014 Ledger: The complete record of account transactions."], ["Journal entry","Profession term \u2014 Journal entry: The basic accounting record."], ["Reconciliation","Profession term \u2014 Reconciliation: Matching records to statements."], ["Audit","Profession term \u2014 Audit: Independent examination of financial statements."], ["CPA","Profession term \u2014 CPA: Certified Public Accountant."], ["EA","Profession term \u2014 EA: Enrolled Agent: tax practice credential."], ["W-2","Profession term \u2014 W-2: Employee wage reporting form."], ["1099","Profession term \u2014 1099: Contractor and miscellaneous income reporting."], ["Quarterly estimates","Profession term \u2014 Quarterly estimates: Prepaid tax installments."], ["Bookkeeping","Profession term \u2014 Bookkeeping: The daily recording of transactions."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
